    (?P<number>\d+(?:\.\d+)?)
    | (?P<name>[A-Za-z]+\d*)
    | (?P<op>[+\-*/^()])
    | (?P<ws>\s+)
    | (?P<bad>.)
    """,
    re.VERBOSE,
)


